__NUXT_JSONP__("/svet/mesto/hafnarfjordur", (function(a,b,c,d,e,f,g,h,i,j,k,l,m,n,o,p,q,r,s,t,u,v,w){return {data:[{place:[{id:i,id_state:j,name:k,population:29123,area:143.05,altitude:l,slug:m,information_chatgpt:"\u003Cp\u003EHafnarfjörður je město ležící v jihozápadním Islandu, nedaleko hlavního města Reykjavíku. S více než 29 000 obyvateli je druhým největším městem na Islandu. Jeho poloha poblíž moře a přírodní krása dělají z Hafnarfjörðuru atraktivní turistickou destinaci.\u003C\u002Fp\u003E\n\u003Cp\u003EHafnarfjörður je známý svým bohatým dědictvím a přítomností elfů. Podle místního folkloru je město domovem mnoha elfů a lidé se zde snaží udržovat jejich přítomnost a respektovat jejich prostředí. V centru města najdete malé sochy elfů a průvodce vám může vyprávět o místních legendách spojených s těmito mystickými bytostmi.\u003C\u002Fp\u003E\n\u003Cp\u003EJednou z hlavních turistických atrakcí v Hafnarfjörðuru je Poddsvíin (\"Podzemí\"), což je stará část města s úzkými uličkami a zachovalou architekturou. Zde můžete prozkoumat historické budovy, restaurace, galerie a obchody s tradičním islandským zbožím. Poddsvíin je také známé pro svůj tradiční trh, kde můžete ochutnat místní speciality a zakoupit suvenýry.\u003C\u002Fp\u003E\n\u003Cp\u003EHafnarfjörður je také známý svými přírodními krásami. Nedaleko města se nachází krásná přírodní rezervace Heiðmörk, která nabízí rozsáhlé lesy, jezera a stezky pro pěší turistiku. Toto přírodní území je oblíbené pro pikniky, procházky a cyklistiku. Hafnarfjörður je také výchozím bodem pro návštěvu horského masivu Esja, který nabízí úchvatné výhledy na okolní krajinu.\u003C\u002Fp\u003E\n\u003Cp\u003EMěsto je také bohaté na kulturní akce a festivaly. Každoročně se zde koná Hátíð hafsins (Slavnost moře), která slaví vztah města k oceánu. Během této slavnosti se pořádají koncerty, divadelní představení a tradiční islandské tance. V průběhu roku se také konají různé umělecké a hudební akce, které přitahují návštěvníky z celého Islandu.\u003C\u002Fp\u003E\n\u003Cp\u003ENavštěvování Hafnarfjörðuru je skvělým způsobem, jak objevovat krásy Islandu mimo hlavní město. Kombinace historie, kultury a přírodních krás dělá z tohoto města fascinující a unikátní cíl pro cestovatele.\u003C\u002Fp\u003E",coordinates:[{latitude:64.0646,longitude:-21.9898}],biggest:"yes",type_place:c,id_image_cover:a,id_image_hero:a,affiliate:[{name:n,value:o}],alerts:a,zoom:[{google:l,booking:11}],parking:a,information_author:a,importance:d,seo_tags:a}],imagePlace:[],placeState:[{tld:".is",name:"Island",area:103000,population:368010,slug:p,id_continent:f,information_chatgpt:"\u003Cp\u003EIsland, oficiálně známý jako Islandská republika, je ostrovní stát v severní Evropě. S rozlohou 103 000 km² je to největší ostrov na světě, který není součástí kontinentu. Island je znám svými dramatickými krajinami, které zahrnují sopky, gejzíry, ledovce a řeky. Díky svému umístění na hranici eurasijské a severoamerické tektonické desky je Island také domovem mnoha geotermálních jevů.\u003C\u002Fp\u003E\n\u003Cp\u003EIslandská kultura je bohatá a unikátní. Islandský jazyk je starodávný a má mnoho archaických rysů, což z něj činí jednu z nejstarších živých jazykových forem v Evropě. Islandská literatura je také velmi důležitá pro islandskou kulturu a zahrnuje díla jako například ságy, které vyprávějí příběhy islandských osadníků v době středověku.\u003C\u002Fp\u003E\n\u003Cp\u003EIslandská ekonomika je založena na rybolovu, těžbě geotermální energie a turismu. Turisté z celého světa přicházejí na Island, aby viděli jeho jedinečnou přírodu, například národní park Vatnajökull, který je domovem největšího ledovce v Evropě, nebo Modrá laguna, termální koupaliště s modrou vodou obklopené černými lávovými poli.\u003C\u002Fp\u003E\n\u003Cp\u003EVzhledem k poloze Islandu v severním Atlantiku má ostrov velmi drsné a proměnlivé klima. Průměrná teplota v létě se pohybuje kolem 10 °C, ale v zimě může klesnout až na -10 °C. Island má také mnoho míst, kde je možné pozorovat polární záři, což je velkou atrakcí pro turisty, kteří přijíždějí v zimě.\u003C\u002Fp\u003E\n\u003Cp\u003EVzhledem k izolované poloze Islandu má ostrov vlastní ekosystém a je domovem mnoha endemických druhů zvířat a rostlin. Mezi ně patří například arktické lišky, sobi, tuleňové a ohrožené druhy ptáků jako je koliha malá.\u003C\u002Fp\u003E",currency_code:"ISK",currency_name:"islandská koruna",money_prices:[{name:"Taxi (cena za km)",value:g,date_update:e},{name:"Hlavní jídlo",value:3500,date_update:e},{name:"Chleba",value:q,date_update:e},{name:"Mléko",value:r,date_update:e},{name:"Voda (500ml)",value:r,date_update:e},{name:"Espresso",value:g,date_update:e},{name:"Zmrzlina (jeden kopeček)",value:q,date_update:e},{name:"Pivo",value:1000,date_update:e},{name:"Krabička cigaret",value:a,date_update:e},{name:"Bic Mac",value:a,date_update:e},{name:"Coca Cola (500ml)",value:g,date_update:e}],phone_numbers_emergency:[{name:"Mezinárodní tísňová linka",value:s,date_update:b},{name:"Policie",value:"444-1000",date_update:b},{name:"Hasiči",value:"444-6000",date_update:b},{name:"Zdravotnická záchranná služba",value:s,date_update:b},{name:"Turistická policie",value:"444-0500",date_update:b},{name:"Horská záchranná služba",value:"570-5900",date_update:b},{name:"Pobřežní záchranná služba",value:"470-5500",date_update:b}],phone_prefix:"+354",coordinates:[{latitude:"64.9631",longitude:"-19.0208"}],people_religion:[{name:"Bez vyznání",value:"80.3%"},{name:"Křesťanství",value:"11.6%"},{name:"Heiðni (Asatro)",value:"0.9%"},{name:"Jiné náboženství",value:"7.2%"}],people_nationality:[{name:"Islandci",value:"92.2%"},{name:"Poláci",value:"1.2%"},{name:"Litvíni",value:t},{name:"Němci",value:t},{name:"Dánové",value:"0.6%"},{name:"Jiné národnosti",value:"4.4%"}],visitors_entry:[{name:"Občanský průkaz",value:"Pro vstup na Island stačí mít platný občanský průkaz. Platí to i pro občany České republiky, která je součástí Evropské unie a Schengenského prostoru.",date_update:b},{name:"Cestovní pas",value:"Pro vstup na Island je potřeba mít platný cestovní pas pouze v případě, že občan nemá platný občanský průkaz. Platí to i pro občany České republiky, která je součástí Evropské unie a Schengenského prostoru.",date_update:b},{name:"Vízum",value:"Občané České republiky a dalších zemí Evropské unie a Schengenského prostoru nepotřebují pro vstup na Island žádné vízum, pokud plánují zůstat na ostrově kratší dobu než 90 dní. Vízum je potřeba pro delší pobyt nebo při pracovních aktivitách na Islandu. Podrobné informace o vízech lze získat na oficiálních stránkách islandského ministerstva zahraničních věcí.",date_update:b},{name:"Očkování",value:"Pro vstup na Island není povinné mít žádné očkování. Nicméně v souvislosti s probíhající pandemií COVID-19 mohou být nařízeny určité podmínky vstupu, např. prezentace negativního testu na COVID-19 nebo dokladu o prodělané nemoci. Doporučuje se být v průběhu cesty na Islandu opatrný a řídit se platnými doporučeními ohledně bezpečnosti a hygieny. Podrobné informace lze získat na oficiálních stránkách islandského ministerstva zdravotnictví.",date_update:b},{name:"Cestovní pojištění",value:"Pro vstup na Island není povinné mít cestovní ani zdravotní pojištění. Nicméně se doporučuje sjednat si pojištění, aby v případě potřeby byly hrazeny náklady na lékařskou péči nebo repatriaci.",date_update:b},{name:"Bezpečnostní situace",value:"Island je obecně považován za bezpečnou zemi s nízkou mírou kriminality. Nicméně je třeba být obezřetný a dodržovat základní bezpečnostní opatření, zejména v oblasti turistických atrakcí a v přírodě, kde hrozí riziko nebezpečí způsobeného povětrnostními podmínkami a přírodními jevy.",date_update:b},{name:"Další informace",value:"Při cestování na Island se doporučuje dodržovat zákazy a omezení týkající se ochrany přírody a zvířat, stejně jako respektovat místní zvyklosti a kulturu. Důležité je také informovat se o povětrnostních podmínkách a případných uzavírkách silnic a turistických tras. Vzhledem k rozsáhlému vulkanickému původu země a aktivním sopkám je nutné sledovat aktuální situaci a pokyny místních orgánů.",date_update:b}],type_place:u,id_image_cover:h,id_image_hero:h,id_city_main:v,affiliate:[{name:n,value:o}],mpz:"IS",alerts:a,zoom:[{google:5,booking:6}],ids_neighboring_countries:[],organization:a,apps:a,links:a,information_author:a,seo_tags:a,language_phrases:a,wall_sockets:a,id:j,facts:a}],imageState:[{id:h,name:p,source:"\u002Fworld\u002Fstates\u002F",date_create:"2023-05-03T20:14:00.749527+00:00",type:u,author:"pixabay.com"}],placeContinent:[{id:f,slug:"evropa",name:"Evropa",area:10180000,population:746000000,population_density:73.22,number_states:44,information_chatgpt:"\u003Cp\u003E\u003Cb\u003EEvropa\u003C\u002Fb\u003E je druhým nejmenším kontinentem na světě, ale zároveň se jedná o jednu z nejvíce rozmanitých oblastí na planetě. Nachází se zde mnoho historických a kulturních památek, překrásných přírodních scenérií a mnoho dalších atrakcí, což z ní dělá jednu z nejnavštěvovanějších turistických destinací na světě.\u003C\u002Fp\u003E\n\u003Cp\u003E\u003Cb\u003EEvropa\u003C\u002Fb\u003E má dlouhou a bohatou historii. Na kontinentě se odehrály mnohé důležité události, jako například římská říše, středověké křížové výpravy, renesance, průmyslová revoluce a dvě světové války. Tato historie se odráží v architektuře, muzeích a dalších kulturních památkách, které jsou na kontinentu k vidění.\u003C\u002Fp\u003E\n\u003Cp\u003EV \u003Cb\u003EEvropě\u003C\u002Fb\u003E se nachází mnoho zajímavých měst. Například \u003Cb\u003E\u003Ca href=\"https:\u002F\u002Fwww.frytolnacestach.cz\u002Fsvet\u002Fmesto\u002Fpariz\"\u003EPaříž\u003C\u002Fa\u003E\u003C\u002Fb\u003E, \u003Cb\u003E\u003Ca href=\"https:\u002F\u002Fwww.frytolnacestach.cz\u002Fsvet\u002Fmesto\u002Flondyn\"\u003ELondýn\u003C\u002Fa\u003E\u003C\u002Fb\u003E, \u003Cb\u003E\u003Ca href=\"https:\u002F\u002Fwww.frytolnacestach.cz\u002Fsvet\u002Fmesto\u002Frim\"\u003EŘím\u003C\u002Fa\u003E\u003C\u002Fb\u003E, \u003Cb\u003E\u003Ca href=\"https:\u002F\u002Fwww.frytolnacestach.cz\u002Fsvet\u002Fmesto\u002Fbarcelona\"\u003EBarcelona\u003C\u002Fa\u003E\u003C\u002Fb\u003E, \u003Cb\u003E\u003Ca href=\"https:\u002F\u002Fwww.frytolnacestach.cz\u002Fsvet\u002Fmesto\u002Fpraha\"\u003EPraha\u003C\u002Fa\u003E\u003C\u002Fb\u003E, \u003Cb\u003E\u003Ca href=\"https:\u002F\u002Fwww.frytolnacestach.cz\u002Fsvet\u002Fmesto\u002Fberlin\"\u003EBerlín\u003C\u002Fa\u003E\u003C\u002Fb\u003E a \u003Cb\u003E\u003Ca href=\"https:\u002F\u002Fwww.frytolnacestach.cz\u002Fsvet\u002Fmesto\u002Famsterdam\"\u003EAmsterdam\u003C\u002Fa\u003E\u003C\u002Fb\u003E jsou velmi oblíbenými cíli turistů. Tyto města nabízejí nejen historické památky, ale také vynikající kuchyni, noční život a mnoho možností pro nákupy.\u003C\u002Fp\u003E\n\u003Cp\u003EPřírodní krása \u003Cb\u003EEvropy\u003C\u002Fb\u003E je také úžasná. Nachází se zde krásné pláže, hory, řeky a jezera. \u003Cb\u003EAlpské hory\u003C\u002Fb\u003E nabízejí překrásné scenérie, skvělé podmínky pro lyžování a další outdoorové aktivity. Národní parky, jako třeba \u003Cb\u003EPlitvická jezera\u003C\u002Fb\u003E v \u003Cb\u003E\u003Ca href=\"https:\u002F\u002Fwww.frytolnacestach.cz\u002Fsvet\u002Fmesto\u002Fchorvatsko\"\u003EChorvatsku\u003C\u002Fa\u003E\u003C\u002Fb\u003E, \u003Cb\u003EKrkonošský národní park\u003C\u002Fb\u003E v \u003Cb\u003E\u003Ca href=\"https:\u002F\u002Fwww.frytolnacestach.cz\u002Fsvet\u002Fmesto\u002Fcesko\"\u003EČeské republice\u003C\u002Fa\u003E\u003C\u002Fb\u003E nebo \u003Cb\u003ENárodní park Durmitor\u003C\u002Fb\u003E v \u003Cb\u003E\u003Ca href=\"https:\u002F\u002Fwww.frytolnacestach.cz\u002Fsvet\u002Fmesto\u002Fcerna-hora\"\u003EČerné Hoře\u003C\u002Fa\u003E\u003C\u002Fb\u003E, jsou dalšími příklady nádherných přírodních scenérií, které stojí za návštěvu.\u003C\u002Fp\u003E\n  \u003Cp\u003E\u003Cb\u003EEvropa\u003C\u002Fb\u003E také nabízí širokou škálu kulturních aktivit. Existují zde mnohé umělecké festivaly, výstavy, divadelní představení a koncerty, které jsou pořádány po celém kontinentu. Mnoho měst také pořádá tradiční slavnosti a jarmarky, kde se můžete seznámit s místními tradicemi a kulturou.\u003C\u002Fp\u003E\n  \u003Cp\u003EPři návštěvě \u003Cb\u003EEvropy\u003C\u002Fb\u003E si určitě nenechte ujít místní kuchyni. Každá země má své vlastní speciality a chuťě\u003C\u002Fp\u003E\u003Cp\u003EMezi nejznámější evropské kuchyně patří \u003Cb\u003Eitalská\u003C\u002Fb\u003E, \u003Cb\u003Efrancouzská\u003C\u002Fb\u003E a \u003Cb\u003Ešpanělská\u003C\u002Fb\u003E. \u003Cb\u003EItalská kuchyně\u003C\u002Fb\u003E je známá svými \u003Cb\u003E\u003Ca href=\"https:\u002F\u002Fwww.frytolnacestach.cz\u002Fjidlo\u002Fpasta\"\u003Etěstovinami\u003C\u002Fa\u003E\u003C\u002Fb\u003E, \u003Cb\u003E\u003Ca href=\"https:\u002F\u002Fwww.frytolnacestach.cz\u002Fjidlo\u002Fpizza\"\u003Epizzou\u003C\u002Fa\u003E\u003C\u002Fb\u003E a \u003Cb\u003Ezmrzlinou\u003C\u002Fb\u003E. \u003Cb\u003EFrancouzská kuchyně\u003C\u002Fb\u003E nabízí širokou škálu různých pokrmů, jako například sýry, pečivo, maso a víno. \u003Cb\u003EŠpanělská kuchyně\u003C\u002Fb\u003E je známá svými \u003Cb\u003E\u003Ca href=\"https:\u002F\u002Fwww.frytolnacestach.cz\u002Fjidlo\u002Ftapas\"\u003Etapas\u003C\u002Fa\u003E\u003C\u002Fb\u003E, \u003Cb\u003E\u003Ca href=\"https:\u002F\u002Fwww.frytolnacestach.cz\u002Fjidlo\u002Fpaella\"\u003Epaellou\u003C\u002Fa\u003E\u003C\u002Fb\u003E a \u003Cb\u003Esangriou\u003C\u002Fb\u003E. Kromě těchto kuchyní jsou v \u003Cb\u003EEvropě\u003C\u002Fb\u003E také velmi oblíbené pokrmy jako \u003Cb\u003Eněmecké klobásy\u003C\u002Fb\u003E, \u003Cb\u003Eanglické snídaně\u003C\u002Fb\u003E, \u003Cb\u003Eholandský sýr\u003C\u002Fb\u003E a mnoho dalšího.\u003C\u002Fp\u003E\n  \u003Cp\u003E\u003Cb\u003EEvropa\u003C\u002Fb\u003E také nabízí mnoho možností pro sportovní aktivity. Mezi nejpopulárnější sporty patří fotbal, hokej, tenis a cyklistika. Na kontinentu se také nachází mnoho golfových hřišť, lyžařských středisek a dalších sportovních zařízení. V posledních letech se stále více lidí zajímá o ekoturistiku, a tak se nabízí možnost podniknout pěší túru nebo cyklistický výlet a objevovat krásy evropské přírody.\u003C\u002Fp\u003E\n\u003Cp\u003E\u003Cb\u003EEvropa\u003C\u002Fb\u003E je jedním z nejlepších míst pro cestování, nabízí mnoho možností pro každého cestovatele. Díky rozmanitosti kontinentu si každý najde to svoje, co ho zaujme. Záleží pouze na vás, zda si zvolíte kulturní zážitky, přírodní krásy, sportovní aktivity nebo si jen tak užijete místní kuchyni a pohodu.\u003C\u002Fp\u003E",coordinates:[{latitude:47.497912,longitude:19.040235}],type_place:"continent",id_image_cover:f,id_image_hero:f,zoom:[{google:w,booking:w}],information_author:a,seo_tags:a}],placesCities:[{id:1064,id_image_cover:a,importance:d,slug:"akranes",type_place:c,name:"Akranes"},{id:1061,id_image_cover:a,importance:d,slug:"akureyri",type_place:c,name:"Akureyri"},{id:1062,id_image_cover:a,importance:d,slug:"garoabar",type_place:c,name:"Garðabær"},{id:i,id_image_cover:a,importance:d,slug:m,type_place:c,name:k},{id:1063,id_image_cover:a,importance:d,slug:"keflavik",type_place:c,name:"Keflavík"},{id:1059,id_image_cover:a,importance:d,slug:"kopavogur",type_place:c,name:"Kópavogur"},{id:1066,id_image_cover:a,importance:d,slug:"njarovik",type_place:c,name:"Njarðvík"},{id:v,id_image_cover:a,importance:d,slug:"reykjavik",type_place:c,name:"Reykjavik"},{id:1067,id_image_cover:a,importance:d,slug:"saudarkrokur",type_place:c,name:"Saudárkrókur"},{id:1065,id_image_cover:a,importance:d,slug:"selfoss",type_place:c,name:"Selfoss"}],imagesCities:a}],fetch:{"OrganismsoPlaceTeaserSpotsComponent:0":{spots:[],images:a},"OrganismsoSidebarListComponent:0":{events:[],images:a}},mutations:[]}}(null,"05-2023","city","biggest","05-2021",4,400,272,1060,109,"Hafnarfjörður",10,"hafnarfjordur","booking",true,"island",500,250,"112","0.8%","state",1058,3)));